def disease_chunks() -> list[dict[str, object]]:
    chunks: list[dict[str, object]] = []
    for disease, rules in DISEASE_RULES.items():
        for index, rule in enumerate(rules, start=1):
            rule_code = f"{disease.replace(' ', '_')}-{index:02d}"
            focus = rule["focus"]
            evidence = rule["evidence"]
            chunks.append(
                {
                    "disease_tag": disease,
                    "rule_code": rule_code,
                    "evidence_text": evidence,
                    "chunk_text": (
                        f"Disease: {disease}. Dietary focus: {focus}. "
                        f"Evidence: {evidence} Retrieval cues: nutrition label, {focus}, {disease}, dietary safety."
                    ),
                    "metadata": {
                        "condition": disease,
                        "nutrient_focus": focus,
                        "corpus": "week3_disease_dietary_rules",
                        "version": "2026-05-13",
                    },
                }
            )
    return chunks
